        <button class="nav-button" type="button" data-section="programmes"><span class="nav-icon" aria-hidden="true">▣</span>Programmes</button>
        <button class="nav-button" type="button" data-section="study"><span class="nav-icon" aria-hidden="true">◷</span>Mode of Study</button>
