    </nav>
    <div class="sidebar-bottom"><strong>Content administration</strong><span>Mukuba University website</span></div>
</aside>
<div class="scrim" id="scrim"></div>
<div class="workspace">
    <header class="topbar"><div class="top-left"><button class="menu-toggle" id="menu-toggle" type="button" aria-label="Open navigation" aria-expanded="false" aria-controls="sidebar">☰</button><div class="crumb">Website <span aria-hidden="true">/</span> <strong id="breadcrumb">Overview</strong></div></div><div class="top-right"><a class="site-link" href="{{ url('/') }}" target="_blank" rel="noopener noreferrer">View website ↗</a><div class="profile" aria-label="Signed in as Site Administrator"><span class="avatar" aria-hidden="true">SA</span><span class="profile-copy"><strong>Site Administrator</strong><span>Content manager</span></span></div></div></header>
    <main class="main">
        <section class="view active" data-view="overview" aria-labelledby="overview-title">
            <div class="page-heading"><div><p class="eyebrow">Website administration</p><h1 id="overview-title">Good morning</h1><p class="heading-note">Manage the content visitors see across Mukuba University’s website.</p></div><button class="primary" type="button" data-create>＋ Add content</button></div>
            <div class="stats" aria-label="Website content totals">
                <article class="stat" data-stat="news"><span class="stat-label">News &amp; events</span><strong class="stat-value" data-stat="news">5</strong><div class="stat-foot">Published on the homepage</div></article>
                <article class="stat" data-stat="schools"><span class="stat-label">Schools</span><strong class="stat-value" data-stat="schools">5</strong><div class="stat-foot">Academic schools</div></article>
                <article class="stat" data-stat="programmes"><span class="stat-label">Programmes</span><strong class="stat-value" data-stat="programmes">3</strong><div class="stat-foot">Programme categories</div></article>
                <article class="stat" data-stat="study"><span class="stat-label">Study &amp; stay</span><strong class="stat-value" data-stat="study">2</strong><div class="stat-foot">Study modes listed</div></article>
            </div>
            <div class="overview-grid">
                <section class="panel"><div class="panel-head"><div><h2>Recently published</h2><p>Latest items currently represented on the website</p></div><button class="secondary" type="button" data-go="news">View all</button></div><div class="activity-list">
                    <div class="activity"><span class="mark" aria-hidden="true">▤</span><span><strong>Applications are now open</strong><small>News &amp; Events · Admissions</small></span><time>Today</time></div>
                    <div class="activity"><span class="mark" aria-hidden="true">▤</span><span><strong>12th graduation ceremony</strong><small>News &amp; Events · Upcoming event</small></span><time>Yesterday</time></div>
                    <div class="activity"><span class="mark" aria-hidden="true">⌂</span><span><strong>School of Engineering</strong><small>Schools · Academic information</small></span><time>Sep 24</time></div>
                    <div class="activity"><span class="mark" aria-hidden="true">▣</span><span><strong>Bachelor’s Degree Programmes</strong><small>Programmes · Undergraduate</small></span><time>Sep 21</time></div>
                </div></section>
                <section class="panel"><div class="panel-head"><div><h2>Manage a section</h2><p>Jump straight to website content</p></div></div><div class="quick-links">
                    <button class="quick-link" type="button" data-go="news"><span>News &amp; Events</span><span>→</span></button><button class="quick-link" type="button" data-go="schools"><span>Schools</span><span>→</span></button><button class="quick-link" type="button" data-go="programmes"><span>Programmes</span><span>→</span></button><button class="quick-link" type="button" data-go="study"><span>Mode of Study</span><span>→</span></button><button class="quick-link" type="button" data-go="accommodation"><span>Accommodation</span><span>→</span></button>
                </div></section>
            </div>
        </section>
        <section class="view" data-view="news" aria-labelledby="news-title"><div class="page-heading"><div><p class="eyebrow">Homepage content</p><h1 id="news-title">News &amp; Events</h1><p class="heading-note">Manage announcements, university news and upcoming events.</p></div><button class="primary" type="button" data-create>＋ Add news or event</button></div><div class="toolbar"><p><strong data-count="news">5</strong> items in this section</p><button class="secondary" type="button" data-create>＋ Add item</button></div><div class="panel table-wrap"><table><thead><tr><th>Title</th><th>Summary</th><th>Status</th><th>Updated</th><th>Actions</th></tr></thead><tbody id="list-news"></tbody></table></div></section>
        <section class="view" data-view="schools" aria-labelledby="schools-title"><div class="page-heading"><div><p class="eyebrow">Academic structure</p><h1 id="schools-title">Schools</h1><p class="heading-note">Update school names and the information shown to prospective students.</p></div><button class="primary" type="button" data-create>＋ Add school</button></div><div class="toolbar"><p><strong data-count="schools">5</strong> schools in this section</p><button class="secondary" type="button" data-create>＋ Add item</button></div><div class="panel table-wrap"><table><thead><tr><th>School</th><th>Summary</th><th>Status</th><th>Updated</th><th>Actions</th></tr></thead><tbody id="list-schools"></tbody></table></div></section>
        <section class="view" data-view="programmes" aria-labelledby="programmes-title"><div class="page-heading"><div><p class="eyebrow">Academic offerings</p><h1 id="programmes-title">Programmes</h1><p class="heading-note">Manage programme categories and their website descriptions.</p></div><button class="primary" type="button" data-create>＋ Add programme</button></div><div class="toolbar"><p><strong data-count="programmes">3</strong> programme categories</p><button class="secondary" type="button" data-create>＋ Add item</button></div><div class="panel table-wrap"><table><thead><tr><th>Programme</th><th>Summary</th><th>Status</th><th>Updated</th><th>Actions</th></tr></thead><tbody id="list-programmes"></tbody></table></div></section>
        <section class="view" data-view="study" aria-labelledby="study-title"><div class="page-heading"><div><p class="eyebrow">Learning options</p><h1 id="study-title">Mode of Study</h1><p class="heading-note">Maintain the study modes available across the website.</p></div><button class="primary" type="button" data-create>＋ Add study mode</button></div><div class="toolbar"><p><strong data-count="study">2</strong> study modes</p><button class="secondary" type="button" data-create>＋ Add item</button></div><div class="panel table-wrap"><table><thead><tr><th>Study mode</th><th>Summary</th><th>Status</th><th>Updated</th><th>Actions</th></tr></thead><tbody id="list-study"></tbody></table></div></section>
        <section class="view" data-view="accommodation" aria-labelledby="accommodation-title"><div class="page-heading"><div><p class="eyebrow">Student life</p><h1 id="accommodation-title">Accommodation</h1><p class="heading-note">Manage accommodation details and availability information.</p></div><button class="primary" type="button" data-create>＋ Add accommodation</button></div><div class="toolbar"><p><strong data-count="accommodation">2</strong> accommodation listings</p><button class="secondary" type="button" data-create>＋ Add item</button></div><div class="panel table-wrap"><table><thead><tr><th>Listing</th><th>Summary</th><th>Status</th><th>Updated</th><th>Actions</th></tr></thead><tbody id="list-accommodation"></tbody></table></div></section>
    </main>
</div>
<div class="overlay" id="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><form class="dialog" id="content-form"><div class="dialog-head"><div><h2 id="dialog-title">Add content</h2><p id="dialog-description">Create an item for this website section.</p></div><button class="dialog-close" type="button" data-close aria-label="Close dialog">×</button></div><input type="hidden" id="item-id"><div class="field"><label for="item-title">Title</label><input id="item-title" required maxlength="120" placeholder="Enter a title"></div><div class="field"><label for="item-summary">Summary</label><textarea id="item-summary" maxlength="280" placeholder="Add a short description"></textarea></div><div class="field"><label for="item-status">Status</label><select id="item-status"><option>Published</option><option>Draft</option></select></div><div class="dialog-actions"><button class="secondary" type="button" data-close>Cancel</button><button class="primary" type="submit">Save changes</button></div></form></div>
<script>
(() => {
    const labels={overview:'Overview',news:'News & Events',schools:'Schools',programmes:'Programmes',study:'Mode of Study',accommodation:'Accommodation'};
    const items={
        news:[['Applications are now open','Start your Mukuba University journey and apply for the next intake.','Published','Today'],['12th graduation ceremony','Join us as we celebrate the achievements of our graduating class.','Published','Yesterday'],['Publication of results','Students can review their latest examination results through the academic office.','Published','Sep 25, 2026'],['Moving to semester learning','An update on the transition to semester-based learning.','Published','Sep 18, 2026'],['Student leadership forum','Students and staff shape a stronger campus community.','Draft','Sep 12, 2026']],
        schools:[['School of Mathematics and Natural Sciences','Teaching and research across mathematics and natural sciences.','Published','Sep 24, 2026'],['School of Agriculture and Environmental Sciences','Learning and research for sustainable agriculture and environments.','Published','Sep 24, 2026'],['School of Education','Preparing educators through teaching, research and community engagement.','Published','Sep 20, 2026'],['School of Engineering','Applied engineering education for practical challenges.','Published','Sep 20, 2026'],['School of Medicine','Health sciences education and clinical learning.','Draft','Sep 19, 2026']],
        programmes:[['Diploma Programmes','Explore diploma-level courses currently on offer.','Published','Sep 21, 2026'],['Bachelor’s Degree Programmes','Browse undergraduate degree programmes.','Published','Sep 21, 2026'],['Masters Programmes','Explore postgraduate study opportunities.','Published','Sep 18, 2026']],
        study:[['Fulltime learning mode','On-campus learning for full-time students.','Published','Sep 16, 2026'],['Distance learning mode','Flexible learning options for distance students.','Published','Sep 16, 2026']],
        accommodation:[['Student accommodation','Information about on-campus accommodation for students.','Published','Sep 10, 2026'],['Accommodation enquiries','Contact Student Affairs for room availability and applications.','Draft','Sep 10, 2026']]
    };
    let section='overview';
    const dialog=document.getElementById('dialog'),form=document.getElementById('content-form'),sidebar=document.getElementById('sidebar'),toggle=document.getElementById('menu-toggle'),scrim=document.getElementById('scrim');
    function render(key){
        const body=document.getElementById('list-'+key);
        if(body){body.replaceChildren();items[key].forEach((item,index)=>{
            const row=document.createElement('tr'),name=document.createElement('td'),summary=document.createElement('td'),statusCell=document.createElement('td'),status=document.createElement('span'),updated=document.createElement('td'),actions=document.createElement('td'),group=document.createElement('div'),edit=document.createElement('button'),del=document.createElement('button');
            name.textContent=item[0];summary.textContent=item[1]||'No summary provided';status.className='status'+(item[2]==='Draft'?' draft':'');status.textContent=item[2];statusCell.append(status);updated.textContent=item[3];group.className='row-actions';edit.type=del.type='button';edit.className='row-action';edit.textContent='Edit';del.className='row-action delete';del.textContent='Delete';edit.addEventListener('click',()=>openDialog(key,index));del.addEventListener('click',()=>{if(confirm('Delete “'+item[0]+'” from this preview?')){items[key].splice(index,1);render(key)}});group.append(edit,del);actions.append(group);row.append(name,summary,statusCell,updated,actions);body.append(row);
        });if(!items[key].length){const row=document.createElement('tr'),cell=document.createElement('td');cell.className='empty-row';cell.colSpan=5;cell.textContent='No content here yet. Add an item to get started.';row.append(cell);body.append(row)}}
        document.querySelectorAll('[data-count="'+key+'"]').forEach(el=>el.textContent=items[key].length);const stat=document.querySelector('[data-stat="'+key+'"]');if(stat)stat.textContent=items[key].length;
    }
    function navigate(key){section=key;document.querySelectorAll('.nav-button').forEach(button=>{const selected=button.dataset.section===key;button.classList.toggle('active',selected);button.setAttribute('aria-current',selected?'page':'false')});document.querySelectorAll('.view').forEach(view=>view.classList.toggle('active',view.dataset.view===key));document.getElementById('breadcrumb').textContent=labels[key];if(key!=='overview')render(key);closeSidebar();window.scrollTo({top:0,behavior:'smooth'})}
    function openDialog(key,index){if(key&&key!=='overview')section=key;if(section==='overview')section='news';const editing=Number.isInteger(index),item=editing?items[section][index]:null;document.getElementById('dialog-title').textContent=editing?'Edit content':'Add '+labels[section].toLowerCase();document.getElementById('dialog-description').textContent=editing?'Update this item in '+labels[section]+'.':'This item will be added to '+labels[section]+'.';document.getElementById('item-id').value=editing?String(index):'';document.getElementById('item-title').value=item?item[0]:'';document.getElementById('item-summary').value=item?item[1]:'';document.getElementById('item-status').value=item?item[2]:'Published';dialog.dataset.section=section;dialog.classList.add('open');document.getElementById('item-title').focus()}
    function closeDialog(){dialog.classList.remove('open');form.reset();document.getElementById('item-id').value=''}
    function closeSidebar(){sidebar.classList.remove('open');scrim.classList.remove('open');toggle.setAttribute('aria-expanded','false')}
    document.querySelectorAll('[data-section]').forEach(button=>button.addEventListener('click',()=>navigate(button.dataset.section)));document.querySelectorAll('[data-go]').forEach(button=>button.addEventListener('click',()=>navigate(button.dataset.go)));document.querySelectorAll('[data-create]').forEach(button=>button.addEventListener('click',()=>openDialog(section)));document.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',closeDialog));dialog.addEventListener('click',event=>{if(event.target===dialog)closeDialog()});document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeDialog();closeSidebar()}});toggle.addEventListener('click',()=>{const open=!sidebar.classList.contains('open');sidebar.classList.toggle('open',open);scrim.classList.toggle('open',open);toggle.setAttribute('aria-expanded',String(open))});scrim.addEventListener('click',closeSidebar);
    form.addEventListener('submit',event=>{event.preventDefault();const key=dialog.dataset.section,index=document.getElementById('item-id').value,item=[document.getElementById('item-title').value.trim(),document.getElementById('item-summary').value.trim(),document.getElementById('item-status').value,'Just now'];if(index==='')items[key].unshift(item);else items[key][Number(index)]=item;render(key);closeDialog()});Object.keys(items).forEach(render);
})();
</script>
</body>
</html>
